function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least 1 node.';
  const values = root.filter(v => v !== null);
  if (values.length > 1000) return 'The tree has at most 1000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Every node value is an integer from 0 to 1000.';
  return null;
}

