function averageOfSubtree(root) {
  // List every node, then add up each node's subtree from scratch.
  const all = [root];
  for (let i = 0; i < all.length; i++) {
    if (all[i].left) all.push(all[i].left);
    if (all[i].right) all.push(all[i].right);
  }
  let matches = 0;
  for (const top of all) {
    let total = 0, nodes = 0;
    const stack = [top];
    while (stack.length) {
      const cur = stack.pop();
      total += cur.val;
      nodes += 1;
      if (cur.left) stack.push(cur.left);
      if (cur.right) stack.push(cur.right);
    }
    if (Math.trunc(total / nodes) === top.val) matches++;
  }
  return matches;
}

