function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 10);
  const mode = rand();
  const constant = Math.floor(rand() * 1001);
  // Values cover the full range, a narrow range (many matches), or are all equal.
  const value = () => mode < 0.4 ? Math.floor(rand() * 1001) : mode < 0.85 ? Math.floor(rand() * 6) : constant;
  // Some trees begin with a long downward chain, which makes the recursion deep.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 300) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: value(), left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: value(), left: null, right: null });
  }
  const open = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * open.length);
    const [parent, side] = open[k];
    open[k] = open[open.length - 1];
    open.pop();
    nodes[parent][side] = i;
    nodes.push({ val: value(), left: null, right: null });
    open.push([i, 'left'], [i, 'right']);
  }
  // Level-order list with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
